head.script:
scwin.screenId = "jldinf20000";

///////// 1. 변수 및 선언 영역 /////////

// as-is 메뉴 위치 상태 (bmenu/mmenu)
scwin.dmenus = undefined;
try {
    scwin.dmenus = {
        "bmenu": 4,
        "mmenu": 0
    };
} catch (_e) {
    $c.exception.handleError(_e, { notify: 'none', context: 'jldinf20000' });
}

// as-is 흐름 보존 — 스켈레톤이 대체한 함수가 쓰던 전역 선언
scwin._popupWindow = undefined;
scwin.type = undefined;

///////// 2. 초기화 영역 /////////

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.
/**
 * @method
 * @name onpageload
 * @description 화면 진입점 — 초기화 함수(init_*)를 데이터 의존성 순서로 순차 실행한다.
 * @returns {void}
 * @hidden N
 * @example (body ev:onpageload 바인딩으로 자동 호출)
 */
scwin.onpageload = function () {
    try {
        scwin.init_recvParam(); // 1) 화면 전환 파라미터 수신 (dma_pageContext 확보)
        scwin.init_rowCopy(); // 2) 수신 파라미터를 조회 조건 컴포넌트로 복사
        scwin.init_attrReals(); // 3) 총건수/페이지 안내 문구 동적 렌더
        scwin.init_conds(); // 4) 서버 구분·조회 결과 유무 표시 조건 평가
        scwin.init_entryDefaults(); // 5) 검색구분 라디오 기본값("1") 충전
        scwin.init_datefmt_cal_stdCdGrntStartDd(); // 6) 코드부여 시작일 달력 포맷 점검
        scwin.init_datefmt_cal_stdCdGrntEndDd(); // 7) 코드부여 종료일 달력 포맷 점검
        scwin.init_pageBody(); // 8) 페이징 강조·키/클릭 바인딩·기본 조회기간 설정
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldinf20000.onpageload' });
    }
};

// 진입 파라미터 기본값 (회신표 entry_defaults — 전달분 우선). 진입점이 부르는 초기화 단계.
/**
 * @method
 * @name init_entryDefaults
 * @description dma_DownloadReq.gubunRadio 가 진입 파라미터로도 데이터맵에도 없으면 기본값 "1"(개별종목조회)을 충전한다.
 * @returns {void}
 * @hidden N
 * @example scwin.init_entryDefaults();
 */
scwin.init_entryDefaults = function () {
    const pcDownloadReq = $c.util.getComponent('dma_DownloadReq');
    if (!pcDownloadReq || typeof pcDownloadReq.get !== 'function') {
        console.warn('[sdd] entry_defaults 대상 부재: dma_DownloadReq');
    } else if (($c.data.getParameter('gubunRadio') == null || $c.data.getParameter('gubunRadio') === '') && (pcDownloadReq.get('gubunRadio') == null || pcDownloadReq.get('gubunRadio') === '')) {
        pcDownloadReq.set('gubunRadio', "1");
    }
};

// 속성 EL 실현 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
/**
 * @method
 * @name init_attrReals
 * @description ul_186 영역에 총건수/현재페이지/전체페이지 안내 문구를 동적 렌더한다(dma_page 값이 모두 비어 있으면 빈 문자열).
 * @returns {void}
 * @hidden N
 * @example scwin.init_attrReals();
 */
scwin.init_attrReals = function () {
    const attrReals = [{
        childId: "ul_186",
        attr: "__html",
        fn: function () {
            const total = String($c.data.readValue("dma_page", "total", { silent: true }));
            const currentPage = String($c.data.readValue("dma_page", "currentPage", { silent: true }));
            const pageCount = String($c.data.readValue("dma_page", "pageCount", { silent: true }));
            const hasAny = [total, currentPage, pageCount].some(function (v) {
                return String(v == null ? '' : v).trim() !== '';
            });
            if (!hasAny) {
                return '';
            }
            return "총 <strong id=\"totPage\">" + total + "</strong>건 <span id=\"totPage1\">(" + currentPage + "/" + pageCount + ")</span>";
        }
    }];
    $c.util.applyAttrReals(attrReals);
};

// 런타임 분기 평가 — 공용 $c.util.evalConds (화면은 조건 바인딩 목록만 보유)
// 조건 평가 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
/**
 * @method
 * @name init_conds
 * @description 표시 조건을 평가한다 — c_otherwise_54(체크비트 점검 입력)는 운영 서버(dr1/dr2/real1/real2)가 아닐 때, if_result(페이징 영역)는 result 값이 있을 때 노출한다.
 * @returns {void}
 * @hidden N
 * @example scwin.init_conds();
 */
scwin.init_conds = function () {
    const binds = [{
        id: "c_otherwise_54",
        fn: function () {
            const thisServer = $c.data.readValue("dma_pageContext", "thisServer", { ctx: true, label: "thisServer" });
            return (!((thisServer === 'dr1') || (thisServer === 'dr2') || (thisServer === 'real1') || (thisServer === 'real2')));
        }
    }, {
        id: "if_result",
        fn: function () {
            const result = $c.data.readValue("dma_pageContext", "result", { ctx: true, label: "result" });
            return (!(String(result == null ? '' : result).length === 0));
        }
    }];
    $c.util.evalConds(binds);
};

// dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
/**
 * @method
 * @name init_rowCopy
 * @description dma_pageContext 로 수신한 조회 조건(curSh/isurNm/stdcdfind/comNm/isurCd/코드부여일 기간)을 화면 입력 컴포넌트로 복사한다.
 * @returns {void}
 * @hidden N
 * @example scwin.init_rowCopy();
 */
scwin.init_rowCopy = function () {
    const rowCopies = [{ childId: "ipt_curSh", fn: function () { return String(String($c.data.readValue("dma_pageContext", "curSh", { silent: true }))); } },
        { childId: "ipt_isurNm1", fn: function () { return String(String($c.data.readValue("dma_pageContext", "isurNm", { silent: true }))); } },
        { childId: "ipt_stdCdFind", fn: function () { return String(String($c.data.readValue("dma_pageContext", "stdcdfind", { silent: true }))); } },
        { childId: "ipt_comNm1", fn: function () { return String(String($c.data.readValue("dma_pageContext", "comNm", { silent: true }))); } },
        { childId: "ipt_isurCd1", fn: function () { return String(String($c.data.readValue("dma_pageContext", "isurCd", { silent: true }))); } },
        { childId: "cal_stdCdGrntStartDd", fn: function () { return String(String($c.data.readValue("dma_pageContext", "stdCdGrntStartDd", { silent: true }))); } },
        { childId: "cal_stdCdGrntEndDd", fn: function () { return String(String($c.data.readValue("dma_pageContext", "stdCdGrntEndDd", { silent: true }))); } }];
    $c.data.copyRows(rowCopies);
};

/**
 * @method
 * @name init_datefmt_cal_stdCdGrntStartDd
 * @description 코드부여일 시작일 달력(cal_stdCdGrntStartDd)의 입력 포맷을 yyyyMMdd 로 점검한다.
 * @returns {void}
 * @hidden N
 * @example scwin.init_datefmt_cal_stdCdGrntStartDd();
 */
scwin.init_datefmt_cal_stdCdGrntStartDd = function () {
    $c.date.checkCalendarFormat("cal_stdCdGrntStartDd", "yyyyMMdd");
};

/**
 * @method
 * @name init_datefmt_cal_stdCdGrntEndDd
 * @description 코드부여일 종료일 달력(cal_stdCdGrntEndDd)의 입력 포맷을 yyyyMMdd 로 점검한다.
 * @returns {void}
 * @hidden N
 * @example scwin.init_datefmt_cal_stdCdGrntEndDd();
 */
scwin.init_datefmt_cal_stdCdGrntEndDd = function () {
    $c.date.checkCalendarFormat("cal_stdCdGrntEndDd", "yyyyMMdd");
};

/**
 * @method
 * @name init_pageBody
 * @description 페이징 영역의 현재 페이지를 파란색으로 강조하고, 기본 조회일(dateSetting)·종목명 포커스를 설정한다. gubunRadio 미수신 시 기본 조회기간(최근 1년)을 채운다. (규칙 19: as-is jQuery 종목명 keypress·상품선택 라디오 bind("click") 바인딩은 ipt_isurNm1 ev:onkeydown 과 각 ipt_searchRadioN_onclick 말미의 searchRadioClickCommon 호출로 이관)
 * @returns {void}
 * @hidden N
 * @example scwin.init_pageBody();
 */
scwin.init_pageBody = function () {
    try {
        const pageIndex = $c.util.getComponent('ipt_currentPage').getValue();
        // [규칙 19 보류] 페이징 현재 페이지 강조 — as-is .paging 테이블 DOM 재구성 코드.
        // 전환 마크업에 .paging 테이블이 없고(w2:pageList krxpage_pagenavigator_263 로 대체) 대응 API 가 명확하지 않아 원형 유지(매칭 0건 no-op).
        const pageObj = $('.paging td:contains(' + pageIndex + ')');
        const pagingLeng = pageObj.length;
        for (let i = 0; i < pagingLeng; i++) {
            const obj = pageObj[i];
            const val = $(obj).text();
            if (pageIndex !== val) {
                continue;
            }
            const font = "<font color='blue'>" + val + "</font>";
            $(obj).html(font);
            $(obj).attr("style", "font-size:15px;");
        }
        scwin.dateSetting();
        // 규칙 19: 종목명 Enter 조회 keypress 바인딩 → ipt_isurNm1 ev:onkeydown(scwin.ipt_isurNm1_onkeydown) 이관,
        // 상품선택 라디오 bind("click") → 각 ipt_searchRadioN_onclick 말미의 scwin.searchRadioClickCommon 호출로 이관.
        $c.util.getComponent("ipt_isurNm1").focus();
        const gubunRadioRaw = $c.data.readValue("dma_pageContext", "gubunRadio", { ctx: true, soft: true, label: "gubunRadio" });
        const gubunRadioStr = String(gubunRadioRaw == null ? '' : gubunRadioRaw);
        const gubunRadio = (gubunRadioStr.indexOf('$' + '{') >= 0 ? '' : gubunRadioStr);
        if (gubunRadio === '') {
            scwin.fn_appDate2('stdCdGrntStartDd', 'stdCdGrntEndDd', 12);
        }

    } catch (_ex) {
        $c.exception.handleError(_ex, { context: 'jldinf20000.onpageload' });
    }
};

// 화면 전환 파라미터 수신 — 공용 $c.data.recvParamData (§106, 이름 고정 "paramData"; 실패 표출은 gcc 함수 몫). onpageload 합성 단계.
/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터를 dma_pageContext 로 수신한다(공용 $c.data.recvParamData, 이름 고정 "paramData").
 * @returns {void}
 * @hidden N
 * @example scwin.init_recvParam();
 */
scwin.init_recvParam = function () {
    $c.data.recvParamData('dma_pageContext');
};


///////// 3. 컴포넌트 이벤트 영역 /////////

/**
 * @event
 * @name JLDINF20000_onsubmit
 * @description JLDINF20000 폼 submit 이벤트 — 항상 false 를 반환해 브라우저 기본 제출(페이지 이동)을 차단한다.
 * @param {Object} e 이벤트 객체
 * @returns {Boolean} 항상 false (기본 제출 차단)
 * @hidden N
 * @example (body ev:onsubmit 바인딩으로 자동 호출)
 */
scwin.JLDINF20000_onsubmit = function(e) {
    try {
        const ev = e;
        const event = ev;
        const self = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        return false;
    } catch (_ex) {
        $c.exception.handleError(_ex, { context: 'jldinf20000.JLDINF20000_onsubmit' });
    }
};

/**
 * @event
 * @name ipt_gubunRadio1_onclick
 * @description 검색구분 [개별종목조회] 라디오 클릭 — 검색 조건 영역을 현재 검색구분에 맞게 전환한다(cgSearch(1,'N')).
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 * @example (body ev:onclick 바인딩으로 자동 호출)
 */
scwin.ipt_gubunRadio1_onclick = function(e) {
    try {
        const ev = e;
        const event = ev;
        const self = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        scwin.cgSearch(1,'N');
    } catch (_ex) {
        $c.exception.handleError(_ex, { context: 'jldinf20000.ipt_gubunRadio1_onclick' });
    }
};

/**
 * @event
 * @name ipt_gubunRadio2_onclick
 * @description 검색구분 [발행기관별조회] 라디오 클릭 — 검색 조건 영역을 현재 검색구분에 맞게 전환한다(cgSearch(1,'N')).
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 * @example (body ev:onclick 바인딩으로 자동 호출)
 */
scwin.ipt_gubunRadio2_onclick = function(e) {
    try {
        const ev = e;
        const event = ev;
        const self = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        scwin.cgSearch(1,'N');
    } catch (_ex) {
        $c.exception.handleError(_ex, { context: 'jldinf20000.ipt_gubunRadio2_onclick' });
    }
};

/**
 * @event
 * @name ipt_gubunRadio3_onclick
 * @description 검색구분 라디오(값 3, 숨김) 클릭 — 검색 조건 영역을 현재 검색구분에 맞게 전환한다(cgSearch(2,'N')).
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 * @example (body ev:onclick 바인딩으로 자동 호출)
 */
scwin.ipt_gubunRadio3_onclick = function(e) {
    try {
        const ev = e;
        const event = ev;
        const self = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        scwin.cgSearch(2,'N');
    } catch (_ex) {
        $c.exception.handleError(_ex, { context: 'jldinf20000.ipt_gubunRadio3_onclick' });
    }
};

/**
 * @event
 * @name ipt_isurNm1_onkeyup
 * @description 한글종목명/표준코드 입력 keyup — as-is 전역 fn_boardCheck 로 입력값을 검사한다.
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 * @example (body ev:onkeyup 바인딩으로 자동 호출)
 */
scwin.ipt_isurNm1_onkeyup = function(e) {
    try {
        const ev = e;
        const event = ev;
        const self = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        fn_boardCheck(self);
    } catch (_ex) {
        $c.exception.handleError(_ex, { context: 'jldinf20000.ipt_isurNm1_onkeyup' });
    }
};

/**
 * @event
 * @name ipt_isurNm1_onkeydown
 * @description 한글종목명/표준코드 입력 keydown — Enter(13) 입력 시 1페이지부터 표준코드 목록을 재조회한다(fn_search('1')). (규칙 19: as-is jQuery keypress 바인딩 이관)
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 * @example (body ev:onkeydown 바인딩으로 자동 호출)
 */
scwin.ipt_isurNm1_onkeydown = async function(e) {
    try {
        if (e && e.keyCode === 13) {
            await scwin.fn_search('1');
        }
    } catch (_ex) {
        $c.exception.handleError(_ex, { context: 'jldinf20000.ipt_isurNm1_onkeydown' });
    }
};

/**
 * @event
 * @name btn_openCorpCd_onclick
 * @description 발행기관명 [검색] 버튼 클릭 — 발행기관(법인) 코드 검색 팝업을 연다(open_corp_cd).
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 * @example (body ev:onclick 바인딩으로 자동 호출)
 */
scwin.btn_openCorpCd_onclick = function(e) {
    try {
        const ev = e;
        const event = ev;
        const self = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        scwin.open_corp_cd('isur_cd1','com_nm1');
    } catch (_ex) {
        $c.exception.handleError(_ex, { context: 'jldinf20000.btn_openCorpCd_onclick' });
    }
};

/**
 * @event
 * @name ipt_searchRadio1_onclick
 * @description 상품선택 [전체선택(숨김)] 라디오 클릭 — 검색 조건 영역을 갱신하고 다운로드 버튼을 숨긴다(cgSearch(1,'N')). 이어 조회 유형(ipt_curSh)·페이징을 초기화한다(searchRadioClickCommon('1')).
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 * @example (body ev:onclick 바인딩으로 자동 호출)
 */
scwin.ipt_searchRadio1_onclick = function(e) {
    try {
        const ev = e;
        const event = ev;
        const self = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        scwin.cgSearch(1,'N');
        scwin.searchRadioClickCommon('1');
    } catch (_ex) {
        $c.exception.handleError(_ex, { context: 'jldinf20000.ipt_searchRadio1_onclick' });
    }
};

/**
 * @event
 * @name ipt_searchRadio2_onclick
 * @description 상품선택 [주권] 라디오 클릭 — 검색 조건 영역을 갱신하고 다운로드 버튼을 숨긴다(cgSearch(2,'N')). 이어 조회 유형(ipt_curSh)·페이징을 초기화한다(searchRadioClickCommon('2')).
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 * @example (body ev:onclick 바인딩으로 자동 호출)
 */
scwin.ipt_searchRadio2_onclick = function(e) {
    try {
        const ev = e;
        const event = ev;
        const self = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        scwin.cgSearch(2,'N');
        scwin.searchRadioClickCommon('2');
    } catch (_ex) {
        $c.exception.handleError(_ex, { context: 'jldinf20000.ipt_searchRadio2_onclick' });
    }
};

/**
 * @event
 * @name ipt_searchRadio3_onclick
 * @description 상품선택 [채권] 라디오 클릭 — 검색 조건 영역을 갱신하고 다운로드 버튼을 숨긴다(cgSearch(3,'N')). 이어 조회 유형(ipt_curSh)·페이징을 초기화한다(searchRadioClickCommon('3')).
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 * @example (body ev:onclick 바인딩으로 자동 호출)
 */
scwin.ipt_searchRadio3_onclick = function(e) {
    try {
        const ev = e;
        const event = ev;
        const self = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        scwin.cgSearch(3,'N');
        scwin.searchRadioClickCommon('3');
    } catch (_ex) {
        $c.exception.handleError(_ex, { context: 'jldinf20000.ipt_searchRadio3_onclick' });
    }
};

/**
 * @event
