// 표준 API 조합으로 새로 작성한 검사 함수
/**
 * @method
 * @name fn_appDate2
 * @description 종료일을 서버 오늘로, 시작일을 오늘부터 months 개월 전으로 계산해 시작/종료 달력 컴포넌트에 설정한다(cal_/ipt_/원본 id 순으로 탐색).
 * @param {String} startId 시작일 컴포넌트 id 접미(예: 'stdCdGrntStartDd')
 * @param {String} endId 종료일 컴포넌트 id 접미(예: 'stdCdGrntEndDd')
 * @param {Number} months 소급 개월 수(3/6/12/36)
 * @returns {void}
 * @hidden N
 * @example scwin.fn_appDate2('stdCdGrntStartDd', 'stdCdGrntEndDd', 12);
 */
scwin.fn_appDate2 = function (startId, endId, months) {
    try {
        const endDate = $c.date.getServerDateTime();
        const startDate = $c.date.addMonth(endDate, -Number(months || 0));
        const resolveComp = function (nm) {
            return $c.util.getComponent('cal_' + nm) || $c.util.getComponent('ipt_' + nm) || $c.util.getComponent(String(nm));
        };
        const startComp = resolveComp(String(startId));
        if (startComp && startComp.setValue) {
            startComp.setValue(startDate);
        }
        const endComp = resolveComp(String(endId));
        if (endComp && endComp.setValue) {
            endComp.setValue(endDate);
        }
    } catch (_e) {
        $c.exception.handleError(_e, { notify: 'none', context: 'fn_appDate2' });
    }
};

/**
 * @method
 * @name dateSetting
 * @description dma_pageContext.curDate(yyyyMMdd) 기준 1년/3개월/6개월 전 날짜를 계산해 dma_hiddenStore(ipt_hdOneDate/ipt_hdThreeDate/ipt_hdSixDate)에 보관한다.
 * @returns {void}
 * @hidden N
 * @example scwin.dateSetting();
 */
scwin.dateSetting = function () {
    const curDateRaw = $c.data.readValue("dma_pageContext", "curDate", { ctx: true, soft: true, label: "curDate" });
    const curDateStr = String(curDateRaw == null ? '' : curDateRaw);
    const curDate = (curDateStr.indexOf('$' + '{') >= 0 ? '' : curDateStr);
    const curYY = curDate.substring(0, 4);
    const curMM = curDate.substring(4, 6);
    const curDD = curDate.substring(6, 8);
    const intCurYY = Number(curYY);
    const intCurMM = Number(curMM);
    let bfOneYY = "";
    let bfOneMM = "";
    let calMM = intCurMM - 12;
    if (calMM < 0) {
        bfOneYY = intCurYY - 1;
        bfOneMM = 12 + calMM;
    } else {
        bfOneYY = intCurYY;
        bfOneMM = calMM;
    }
    let bfThreeYY = "";
    let bfThreeMM = "";
    calMM = intCurMM - 3;
    if (calMM < 0) {
        bfThreeYY = intCurYY - 1;
        bfThreeMM = 12 + calMM;
    } else {
        bfThreeYY = intCurYY;
        bfThreeMM = calMM;
    }
    let bfSixYY = "";
    let bfSixMM = "";
    calMM = intCurMM - 6;
    if (calMM < 0) {
        bfSixYY = intCurYY - 1;
        bfSixMM = 12 + calMM;
    } else {
        bfSixYY = intCurYY;
        bfSixMM = calMM;
    }
    const oneDD = new Date(bfOneYY, bfOneMM, curDD);
    const threeDD = new Date(bfThreeYY, bfThreeMM, curDD);
    const sixDD = new Date(bfSixYY, bfSixMM, curDD);
    if (Number(bfOneMM) < 10) {
        bfOneMM = "0" + bfOneMM;
    }
    if (Number(bfThreeMM) < 10) {
        bfThreeMM = "0" + bfThreeMM;
    }
    if (Number(bfSixMM) < 10) {
        bfSixMM = "0" + bfSixMM;
    }
    const oneD = (Number(oneDD.getMonth()) < 10) ? ("0" + oneDD.getMonth()) : oneDD.getMonth();
    const ThD = (Number(threeDD.getMonth()) < 10) ? ("0" + threeDD.getMonth()) : threeDD.getMonth();
    const SxD = (Number(sixDD.getMonth()) < 10) ? ("0" + sixDD.getMonth()) : sixDD.getMonth();
    const oneDt = (Number(oneDD.getDate()) < 10) ? ("0" + oneDD.getDate()) : oneDD.getDate();
    const ThDt = (Number(threeDD.getDate()) < 10) ? ("0" + threeDD.getDate()) : threeDD.getDate();
    const SxDt = (Number(sixDD.getDate()) < 10) ? ("0" + sixDD.getDate()) : sixDD.getDate();
    const bfOneDate = oneDD.getFullYear() + oneD + oneDt;
    const bfThreeDate = threeDD.getFullYear() + ThD + ThDt;
    const bfSixDate = sixDD.getFullYear() + SxD + SxDt;
    const hiddenStore = $c.util.getComponent('dma_hiddenStore');
    (hiddenStore && hiddenStore.set ? hiddenStore.set('ipt_hdOneDate', bfOneDate) : console.warn('[sdd] hiddenStore 부재: ipt_hdOneDate'));
    (hiddenStore && hiddenStore.set ? hiddenStore.set('ipt_hdThreeDate', bfThreeDate) : console.warn('[sdd] hiddenStore 부재: ipt_hdThreeDate'));
    (hiddenStore && hiddenStore.set ? hiddenStore.set('ipt_hdSixDate', bfSixDate) : console.warn('[sdd] hiddenStore 부재: ipt_hdSixDate'));
};


/**
 * @method
 * @name setSearchRadioChecked
 * @description 상품선택(searchRadio) 라디오 중 값이 value 인 컴포넌트(ipt_searchRadio{value})를 선택 상태로 만든다. 대상 컴포넌트가 없으면 as-is(셀렉터 매칭 0건 no-op)와 동일하게 동작 없이 경고만 남긴다. (규칙 19: as-is $('input[name=searchRadio][value=N]').attr("checked", true) 이관)
 * @param {String|Number} value 선택할 상품선택 라디오 값
 * @returns {void}
 * @hidden N
 * @example scwin.setSearchRadioChecked(1);
 */
scwin.setSearchRadioChecked = function (value) {
    const radio = $c.util.getComponent('ipt_searchRadio' + value);
    if (radio && radio.setValue) {
        radio.setValue(String(value));
    } else {
        console.warn('[sdd] searchRadio 라디오 부재: ipt_searchRadio' + value);
    }
};


/**
 * @method
 * @name searchRadioClickCommon
 * @description 상품선택(searchRadio) 라디오 클릭 공통 후처리 — 조회 유형(ipt_curSh)을 클릭한 라디오 값으로 갱신하고 페이징 영역을 1페이지로 초기화한다. (규칙 19: as-is jQuery bind("click") 바인딩을 각 ipt_searchRadioN_onclick 말미 호출로 이관, as-is 실행 순서(인라인 onclick → bind 콜백) 보존)
 * @param {String} value 클릭한 상품선택 라디오 값
 * @returns {void}
 * @hidden N
 * @example scwin.searchRadioClickCommon('2');
 */
scwin.searchRadioClickCommon = function (value) {
    $c.util.getComponent('ipt_curSh').setValue(String(value));
    // [규칙 19 보류] 페이징 초기화 — as-is .paging 테이블 DOM 재구성 코드.
    // 전환 마크업에 .paging 테이블이 없고(w2:pageList 대체) 대응 API 가 명확하지 않아 원형 유지(매칭 0건 no-op).
    $('.paging').empty();
    const resetPaging = "<tr><td style='padding-left:5px'><img diabled src='/img/btn/btn-pprev.gif' alt=''></td>" +
        "<td style='padding-left:5px'><img src='/img/btn/btn-prev.gif' alt='' ></td>" +
        "<td class='bg_pagingbar'></td><td>1</td>" +
        "<td style='padding-left:5px'><img src='/img/btn/btn-next.gif' border='0' ></td>" +
        "<td style='padding-left:5px'><img src='/img/btn/btn-nnext.gif' alt='' ></a></td></tr>";
    $('.paging').append(resetPaging);
};


/**
 * @method
 * @name cgSearch
 * @description 검색구분(gubunRadio) 값에 따라 조건 행(trSearch)을 모두 숨긴 뒤 해당 구분의 조건 행(개별종목/발행기관/상품·일자)만 표시하고, 조회 유형(ipt_curSh)·라디오 선택을 갱신한 다음 다운로드 버튼을 숨긴다.
 * @param {Number} idx 선택할 상품선택(searchRadio) 라디오 값
 * @param {String} check as-is 호출 규약 인자(현재 로직 미사용, 'N' 고정 전달)
 * @returns {void}
 * @hidden N
 * @example scwin.cgSearch(1, 'N');
 */
scwin.cgSearch = function (idx, check) {
    const gubun = $c.util.getComponent("dma_DownloadReq").get("gubunRadio");
    // 규칙 19: $('tr[name=trSearch]').attr("style","display:none;") → 조건 행 그룹(name=trSearch) 4건 hide()
    ["id_isur", "id_com", "id_type", "id_date"].forEach(function (trId) {
        $c.util.getComponent(trId).hide();
    });
    if (gubun === '1') {
        $c.util.getComponent('ipt_curSh').setValue('1');
        scwin.setSearchRadioChecked(idx);
        $c.util.getComponent("id_isur").setStyle("display", "");
        /* unresolved-target intent:set_label — {target}.setLabel({args}) */
        $c.util.getComponent("ipt_isurNm1").focus();
    } else {
        if (gubun === '2') {
            $c.util.getComponent('ipt_curSh').setValue('1');
            scwin.setSearchRadioChecked(idx);
            $c.util.getComponent("id_com").setStyle("display", "");
            /* unresolved-target intent:set_label — {target}.setLabel({args}) */
        } else {
            if (gubun === '3') {
                $c.util.getComponent('ipt_curSh').setValue('2');
                scwin.setSearchRadioChecked(idx);
                $c.util.getComponent("id_com").setStyle("display", "");
                $c.util.getComponent("id_type").setStyle("display", "");
                $c.util.getComponent("id_date").setStyle("display", "");
                $c.util.getComponent('ipt_searchDateRadio1').setValue('1');
                /* unresolved-target intent:set_label — {target}.setLabel({args}) */
            } else {
                $c.util.getComponent('ipt_curSh').setValue('1');
                scwin.setSearchRadioChecked(1);
                $c.util.getComponent("id_isur").setStyle("display", "");
                /* unresolved-target intent:set_label — {target}.setLabel({args}) */
            }
        }
    }
    scwin.fn_viewDownloadBtn("N");
};


/**
 * @method
 * @name fn_viewDownloadBtn
 * @description 다운로드 버튼 영역(downExcel)을 표시("Y")하거나 숨긴다("N").
 * @param {String} div 표시 여부 구분("Y"=표시, "N"=숨김)
 * @returns {void}
 * @hidden N
 * @example scwin.fn_viewDownloadBtn('N');
 */
scwin.fn_viewDownloadBtn = function (div) {
    const downExcel = $c.util.getComponent("downExcel");
    if (div === "Y") {
        (downExcel && downExcel.show ? downExcel.show() : console.warn('[sdd] show 대상 미해결: ' + "downExcel"));
    } else {
        if (div === "N") {
            (downExcel && downExcel.hide ? downExcel.hide() : console.warn('[sdd] hide 대상 미해결: ' + "downExcel"));
        }
    }
};


/**
 * @method
 * @name fn_Download
 * @description 엑셀 다운로드 실행 — 현재는 "조회 내용이 없습니다." 안내 후 즉시 종료한다(이하 as-is 로직 보존: 코드부여일 기간 1년 이내 검증, 조회 조건 hiddenStore 보관, 상품별 다운로드 action 분기 후 tx_fn_Download 호출 — 도달 불가).
 * @returns {void}
 * @hidden N
 * @example await scwin.fn_Download();
 */
scwin.fn_Download = async function () {
    await $c.win.alert("조회 내용이 없습니다.");
    return;
    const startVal = $c.util.getComponent('cal_stdCdGrntStartDd').getValue();
    if ((startVal == null ? '' : String(startVal)) === '') {
        await $c.win.alert('다운로드는 일자를 1년 이내로 설정하여야\n\r사용이 가능합니다.');
        std_cd_grnt_start_dd.focus();
        return;
    } else {
        const endVal = $c.util.getComponent('cal_stdCdGrntEndDd').getValue();
        if ((endVal == null ? '' : String(endVal)) === '') {
            await $c.win.alert('다운로드는 일자를 1년 이내로 설정하여야\n\r사용이 가능합니다.');
            std_cd_grnt_end_dd.focus();
            return;
        } else {
            const startD = $c.util.getComponent('cal_stdCdGrntStartDd').getValue();
            const startN = parseInt(startD.substr(4, 2), 10) - 1;
            const startT = new Date(startD.substr(0, 4), startN, startD.substr(6, 2));
            const endD = $c.util.getComponent('cal_stdCdGrntEndDd').getValue();
            const endN = parseInt(endD.substr(4, 2), 10) - 1;
            const endT = new Date(endD.substr(0, 4), endN, endD.substr(6, 2));
            const apDate = new Date(endT - 365 * 1000 * 60 * 60 * 24);
            if (apDate - startT > 0) {
                await $c.win.alert('다운로드는 일자를 1년 이내로 설정하여야\n\r사용이 가능합니다.');
                std_cd_grnt_start_dd.focus();
                return;
            }
        }
    }
    await $c.win.alert("다운로드는 데이터에 따라 몇초에서 몇분가량 소요될 수 있습니다.");
    const hiddenStore = $c.util.getComponent('dma_hiddenStore');
    (hiddenStore && hiddenStore.set ? hiddenStore.set('ipt_isurCd', ($c.util.getComponent("ipt_isurCd1").getValue() || '')) : console.warn('[sdd] hiddenStore 부재: ipt_isurCd'));
    (hiddenStore && hiddenStore.set ? hiddenStore.set('ipt_comNm', ($c.util.getComponent("ipt_comNm1").getValue() || '')) : console.warn('[sdd] hiddenStore 부재: ipt_comNm'));
    const frm = (document.JLDINF20000 || { elements: [] });
    // 규칙 19: $('#ipt_searchRadioN').is(":checked") → 라디오 컴포넌트 getValue() 값 비교
    if ($c.util.getComponent('ipt_searchRadio10').getValue() === '10') {
        frm.action = "/srch/srch.do?method=srchDownElsdlsList";
    } else {
        if ($c.util.getComponent('ipt_searchRadio11').getValue() === '11') {
            frm.action = "/srch/srch.do?method=srchDownElwList";
        } else {
            if ($c.util.getComponent('ipt_searchRadio16').getValue() === '16') {
                frm.action = "/srch/srch.do?method=srchDownEtnList";
            }
        }
    }
    frm.method = "post";
    frm.target = "iframeExcel";
    await scwin.tx_fn_Download();
};


/**
 * @method
 * @name searchData
 * @description dma_pageContext 로 넘어온 조회 조건(코드부여일 기간·조회 유형·발행기관 코드/명·종목명)을 화면 입력에 복원한다. 기간이 비고 searchRadio1 도 없으면 최근 30일을 기본 기간으로 채운다.
 * @param {Number} idx as-is 호출 규약 인자(현재 로직 미사용)
 * @returns {void}
 * @hidden N
 * @example scwin.searchData(1);
 */
scwin.searchData = function (idx) {
    const startDdRaw = $c.data.readValue("dma_pageContext", "std_cd_grnt_start_dd", { ctx: true, soft: true, label: "std_cd_grnt_start_dd" });
    const startDdStr = String(startDdRaw == null ? '' : startDdRaw);
    let std_cd_grnt_start_dd = (startDdStr.indexOf('$' + '{') >= 0 ? '' : startDdStr);
    const endDdRaw = $c.data.readValue("dma_pageContext", "std_cd_grnt_end_dd", { ctx: true, soft: true, label: "std_cd_grnt_end_dd" });
    const endDdStr = String(endDdRaw == null ? '' : endDdRaw);
    let std_cd_grnt_end_dd = (endDdStr.indexOf('$' + '{') >= 0 ? '' : endDdStr);
    const searchRadio2Raw = $c.data.readValue("dma_pageContext", "searchRadio", { ctx: true, soft: true, label: "searchRadio" });
    const searchRadio2Str = String(searchRadio2Raw == null ? '' : searchRadio2Raw);
    const searchRadio2 = (searchRadio2Str.indexOf('$' + '{') >= 0 ? '' : searchRadio2Str);
    const searchRadio1Raw = $c.data.readValue("dma_pageContext", "searchRadio1", { ctx: true, soft: true, label: "searchRadio1" });
    const searchRadio1Str = String(searchRadio1Raw == null ? '' : searchRadio1Raw);
    const searchRadio1 = (searchRadio1Str.indexOf('$' + '{') >= 0 ? '' : searchRadio1Str);
    const searchRadio = $c.util.getComponent('ipt_curSh').getValue();
    const isurCdRaw = $c.data.readValue("dma_pageContext", "isur_cd", { ctx: true, soft: true, label: "isur_cd" });
    const isurCdStr = String(isurCdRaw == null ? '' : isurCdRaw);
    const isur_cd = (isurCdStr.indexOf('$' + '{') >= 0 ? '' : isurCdStr);
    const isurNmRaw = $c.data.readValue("dma_pageContext", "isur_nm", { ctx: true, soft: true, label: "isur_nm" });
    const isurNmStr = String(isurNmRaw == null ? '' : isurNmRaw);
    const isur_nm = (isurNmStr.indexOf('$' + '{') >= 0 ? '' : isurNmStr);
    const comNmRaw = $c.data.readValue("dma_pageContext", "com_nm", { ctx: true, soft: true, label: "com_nm" });
    const comNmStr = String(comNmRaw == null ? '' : comNmRaw);
    const com_nm = (comNmStr.indexOf('$' + '{') >= 0 ? '' : comNmStr);
    if (std_cd_grnt_start_dd === '11111111') {
        std_cd_grnt_start_dd = '';
    }
    if (std_cd_grnt_end_dd === '99999999') {
        std_cd_grnt_end_dd = '';
    }
    if ((std_cd_grnt_start_dd === "" && std_cd_grnt_end_dd === "") && searchRadio1 === "") {
        const now = new Date();
        const year = now.getFullYear();
        const mon = (now.getMonth() + 1) > 9 ? '' + (now.getMonth() + 1) : '0' + (now.getMonth() + 1);
        const day = now.getDate() > 9 ? '' + now.getDate() : '0' + now.getDate();
        const toDate = year + mon + day;
        const n = parseInt(toDate.substr(4, 2), 10) - 1;
        const st = new Date(toDate.substr(0, 4), n, toDate.substr(6, 2));
        const apDate = new Date(st - 30 * 1000 * 60 * 60 * 24);
        const startDate = apDate.getFullYear() + "" + fnLeg(apDate.getMonth() + 1) + "" + fnLeg(apDate.getDate());
        std_cd_grnt_start_dd = startDate;
        std_cd_grnt_end_dd = toDate;
        $c.util.getComponent('cal_stdCdGrntStartDd').setValue(std_cd_grnt_start_dd);
        $c.util.getComponent('cal_stdCdGrntEndDd').setValue(std_cd_grnt_end_dd);
    }
    // 규칙 19: $('#id').length 존재 확인 → $c.util.getComponent(id) null/undefined 판별
    const hasIsurCd1 = $c.util.getComponent('ipt_isurCd1') != null;
    if (hasIsurCd1) {
        $c.util.getComponent('ipt_isurCd1').setValue(isur_cd);
        $c.util.getComponent('ipt_comNm1').setValue(com_nm);
    }
    const hasIsurNm1 = $c.util.getComponent('ipt_isurNm1') != null;
    if (hasIsurNm1) {
        $c.util.getComponent('ipt_isurNm1').setValue(isur_nm);
    }
    $c.util.getComponent('cal_stdCdGrntStartDd').setValue(std_cd_grnt_start_dd);
    $c.util.getComponent('cal_stdCdGrntEndDd').setValue(std_cd_grnt_end_dd);
    scwin.setSearchRadioChecked(searchRadio);
};


/**
 * @method
 * @name onPopupCode
 * @description 상품 유형별 팝업 높이를 결정한 뒤 유가증권 상세 팝업(jldinf20000p)을 열고, 유형 별칭(122→12, 16→14, 18→15 등)을 정규화해 표준코드와 함께 dma_hiddenStore 에 보관하고 팝업 폼 action 을 설정한다.
 * @param {String} type 상품 유형 코드(mktNm)
 * @param {String} ipt_stdCd 표준코드
 * @returns {void}
 * @hidden N
 * @example await scwin.onPopupCode(r["mktNm"], r["stdCd"]);
 */
scwin.onPopupCode = async function (type, ipt_stdCd) {
    const fm = (document.popup_form || { elements: [] });
    const width = 1000;
    let height = 670;
    if (type === "2") {
        height = 660;
    } else {
        if (type === "3") {
            height = 700;
        } else {
            if (type === "4") {
                height = 620;
            } else {
                if (type === "5") {
                    height = 650;
                } else {
                    if (type === "55") {
                        height = 650;
                    } else {
                        if (type === "6") {
                            height = 520;
                        } else {
                            if (type === "7") {
                                height = 720;
                            } else {
                                if (type === "77") {
                                    height = 820;
                                } else {
                                    if (type === "8") {
                                        height = 660;
                                    } else {
                                        if (type === "9") {
                                            height = 700;
                                        } else {
                                            if (type === "10") {
                                                height = 720;
                                            } else {
                                                if (type === "11") {
                                                    height = 700;
                                                } else {
                                                    if (type === "12") {
                                                        height = 620;
                                                    } else {
                                                        if (type === "122") {
                                                            height = 620;
                                                        } else {
                                                            if (type === "13") {
                                                                height = 350;
                                                            } else {
                                                                if (type === "14") {
                                                                    height = 670;
                                                                } else {
                                                                    if (type === "15") {
                                                                        height = 670;
                                                                    } else {
                                                                        if (type === "16") {
                                                                            height = 620;
                                                                        } else {
                                                                            if (type === "17") {
                                                                                height = 620;
                                                                            } else {
                                                                                if (type === "18") {
                                                                                    height = 620;
                                                                                } else {
                                                                                    height = 670;
                                                                                }
                                                                            }
                                                                        }
                                                                    }
                                                                }
                                                            }
                                                        }
                                                    }
                                                }
                                            }
                                        }
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }
    }
    const popupOptions = { id: "winPop", scrollbars: true, resizable: true, width: "", height: "", type: "pageFramePopup" };
    const popupCodeReq = $c.util.getComponent("dma_onPopupCodeReq");
    scwin._popupWindow = $c.win.openPopup("/jldinf20000p/jldinf20000p.xml", popupOptions, (popupCodeReq ? popupCodeReq.getJSON() : {}));
    if (type === "122") {
        type = "12";
    }
    if (type === "101") {
        type = "10";
    }
    if (type === "102") {
        type = "10";
    }
    if (type === "103") {
        type = "10";
    }
    if (type === "104") {
        type = "10";
    }
    if (type === "16") {
        type = "14";
    }
    if (type === "18") {
        type = "15";
    }
    const hiddenStore = $c.util.getComponent('dma_hiddenStore');
    (hiddenStore && hiddenStore.set ? hiddenStore.set('ipt_stdcdType', type) : console.warn('[sdd] hiddenStore 부재: ipt_stdcdType'));
    (hiddenStore && hiddenStore.set ? hiddenStore.set('ipt_stdCd', ipt_stdCd) : console.warn('[sdd] hiddenStore 부재: ipt_stdCd'));
    fm.action = "/srch/srch.do?method=srchPopup" + type;

};


/**
 * @method
 * @name open_corp_cd
 * @description 발행기관(법인) 코드 검색 공통 팝업(as-is 전역 fn_popupCorpSearch2)을 JLDINF20000 폼 기준으로 연다. formName 은 as-is 전역 계약이라 그대로 둔다.
 * @param {String} item_id 결과 코드가 채워질 항목 id
