 */
scwin.open_corp_cd = function (item_id, item_nm) {
    formName = (document.JLDINF20000 || { elements: [] });
    fn_popupCorpSearch2(formName, item_id, item_nm);
};


/**
 * @method
 * @name fn_search
 * @description 검색구분별 필수 조건(개별종목: 종목명 2byte 초과, 발행기관별: 발행기관 선택)을 검증하고 조건을 dma_hiddenStore 에 보관한 뒤 표준코드 목록을 조회한다(tx_fn_search). 일자구분이 코드부여일("4")이면 다운로드 버튼을 표시한다.
 * @param {String|Number} idx 페이지 구분('1' 이면 1페이지부터 조회)
 * @returns {void}
 * @hidden N
 * @example await scwin.fn_search(1);
 */
scwin.fn_search = async function (idx) {
    const gubun = $c.util.getComponent("dma_DownloadReq").get("gubunRadio");
    const hiddenStore = $c.util.getComponent('dma_hiddenStore');
    if (gubun === '1') {
        if (($c.util.getComponent('ipt_isurNm1').getValue() == null ? '' : String($c.util.getComponent('ipt_isurNm1').getValue())) === '') {
            await $c.win.alert("한글종목명 및 표준코드을 입력하세요.");
            $c.util.getComponent("ipt_isurNm1").focus();
            return;
        }
        if ($c.str.getByteLength($c.util.getComponent('ipt_isurNm1').getValue()) <= 2) {
            await $c.win.alert("한글종목명 및 표준코드을 확인하세요");
            $c.util.getComponent("ipt_isurNm1").focus();
            return;
        }
        scwin.setSearchRadioChecked(1);
        (hiddenStore && hiddenStore.set ? hiddenStore.set('ipt_isurNm', ($c.util.getComponent("ipt_isurNm1").getValue() || '')) : console.warn('[sdd] hiddenStore 부재: ipt_isurNm'));
    } else {
        if (gubun === '2') {
            if (($c.util.getComponent('ipt_comNm1').getValue() == null ? '' : String($c.util.getComponent('ipt_comNm1').getValue())) === '') {
                await $c.win.alert("발행기관을 선택하세요.");
                return;
            }
            scwin.setSearchRadioChecked(1);
            (hiddenStore && hiddenStore.set ? hiddenStore.set('ipt_isurCd', ($c.util.getComponent("ipt_isurCd1").getValue() || '')) : console.warn('[sdd] hiddenStore 부재: ipt_isurCd'));
            (hiddenStore && hiddenStore.set ? hiddenStore.set('ipt_comNm', ($c.util.getComponent("ipt_comNm1").getValue() || '')) : console.warn('[sdd] hiddenStore 부재: ipt_comNm'));
        } else {
            if (gubun === '3') {
                (hiddenStore && hiddenStore.set ? hiddenStore.set('ipt_isurCd', ($c.util.getComponent("ipt_isurCd1").getValue() || '')) : console.warn('[sdd] hiddenStore 부재: ipt_isurCd'));
                (hiddenStore && hiddenStore.set ? hiddenStore.set('ipt_comNm', ($c.util.getComponent("ipt_comNm1").getValue() || '')) : console.warn('[sdd] hiddenStore 부재: ipt_comNm'));
            }
        }
    }
    const frm = (document.JLDINF20000 || { elements: [] });
    if (idx === '1') {
        // 규칙 19: $('input[name=pageIndex]').val("1") → hidden 컴포넌트 ipt_pageIndex(ref: dma_DownloadReq.pageIndex)
        $c.util.getComponent('ipt_pageIndex').setValue("1");
    }
    frm.action = "/srch/srch.do?method=srchList";
    frm.target = "_self";
    blockLoading();
    await scwin.tx_fn_search();
    const dateGubun = $c.util.getComponent("dma_DownloadReq").get("searchDateRadio");
    if (dateGubun === "4") {
        scwin.fn_viewDownloadBtn("Y");
    } else {
        scwin.fn_viewDownloadBtn("N");
    }
};



/**
 * @event
 * @name krxpage_pagenavigator_263_onclick
 * @description 페이지 내비게이터 클릭 — 선택한 페이지 번호로 표준코드 목록을 재조회한다(fn_search).
 * @param {Number} index 이동할 페이지 번호
 * @returns {void}
 * @hidden N
 * @example (body ev:onclick 바인딩으로 자동 호출)
 */
scwin.krxpage_pagenavigator_263_onclick = function (index) {
    scwin.fn_search(index);
};
